public class Compte {
    private double solde;

    public Compte(double initial) {
        if (initial < 0) throw new IllegalArgumentException("solde négatif");
        this.solde = initial;
    }

    public double solde() { return solde; }

    public void retirer(double montant) {
        if (montant <= 0 || montant > solde) throw new IllegalArgumentException("montant invalide");
        solde -= montant;
    }
}

interface Forme {
    double aire();
}

class Cercle implements Forme {
    private final double r;
    Cercle(double r) { this.r = r; }
    public double aire() { return Math.PI * r * r; }
}

Forme f = new Cercle(2);
System.out.println(f.aire());

